  virtual std::shared_future<std::any> fetchTransactionsWithMethod(
      std::any method, std::any code = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(!isEqual(since, std::any{}))) {
                   ::setValue(request, std::string("after"), since);
                 }
                 std::any currency = std::any{};
                 if (isTrue(!isEqual(code, std::any{}))) {
                   currency = this->currency(code);
                 }
                 std::any response = std::any{};
                 if (isTrue(
                         isEqual(method, std::string("privateGetTransfers")))) {
                   response = awaitValue(this->privateGetTransfers(
                       this->extend(request, params)));
                 } else if (isTrue(isEqual(
                                method, std::string("privateGetDeposits")))) {
                   response = awaitValue(
                       this->privateGetDeposits(this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateGetWithdrawals(
                       this->extend(request, params)));
                 }
                 return this->parseTransactions(response, currency, since,
                                                limit);
               })
        .share();
  }

